<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import FpDialog from '@/components/FpDialog.vue'
import {useAuthStore} from '@/stores/auth'
import {useV3ChatRedPacketsStore} from '@/stores/v3ChatRedPackets'
import {getAuthContextVersion} from '@/api/http'
import {packetRisk,type ClaimInput} from '@/api/v3-chat-red-packets'
import {fpConfirm} from '@/composables/useDialog'
const auth=useAuthStore(),store=useV3ChatRedPacketsStore(),gesture=ref<number|string>(''),confirming=ref(false),localError=ref('')
const canClaim=computed(()=>{const d=store.detail;return!!d&&!d.currentUserClaim&&d.got<d.count&&!(d.type==='rockPaperScissors'&&d.sender.id===auth.account?.oId)})
let abort:AbortController|null=null
function cancel(){abort?.abort();abort=null;confirming.value=false}
const identity=()=>JSON.stringify([getAuthContextVersion(),!!auth.accessToken,auth.account?.oId||''])
async function claim(){const d=store.detail;if(!d||!canClaim.value||store.busy||store.pending||confirming.value)return;localError.value='';if(d.type==='rockPaperScissors'&&!(typeof gesture.value==='number'&&Number.isInteger(gesture.value)&&gesture.value>=0&&gesture.value<=2)){localError.value='请先明确选择出拳';return}cancel();const controller=new AbortController();abort=controller;const reader=identity(),choice=gesture.value;confirming.value=true
 const warning=d.type==='heartbeat'?`心跳可能领取负积分并扣款，领取前余额至少为初始奖池${d.poolPoints}积分。` :d.type==='rockPaperScissors'?`猜拳胜者得${d.poolPoints}积分，败者扣${d.poolPoints}积分，平局本人不增减；发送者按结算收回相应积分，税不退。领取前余额至少为${d.poolPoints}积分。`:'将领取一份红包，实际积分以结算结果为准，允许为0。'
 const yes=await fpConfirm({title:packetRisk(d.type)?'确认领取风险':'确认领取红包',message:warning+' 每人只能领取一次，是否继续？',confirmText:packetRisk(d.type)?'接受风险并领取':'确认领取',signal:controller.signal})
 if(yes&&!controller.signal.aborted&&reader===identity()&&store.detail===d){const input:ClaimInput={};if(packetRisk(d.type))input.riskAccepted=true;if(d.type==='rockPaperScissors')input.gesture=choice as number;await store.claim(d.id,d.type,input)}if(abort===controller){abort=null;confirming.value=false}}
watch(()=>store.detail,()=>{cancel();gesture.value='';localError.value=''});watch(identity,cancel,{flush:'sync'});onBeforeUnmount(cancel)
const hand=(g:number)=>['石头','剪刀','布'][g]||'未知'
</script>
<template><FpDialog :open="!!store.selectedId" title="红包详情" :width="560" @close="store.close"><p v-if="store.loading" role="status">正在读取红包…</p><p v-if="store.detailError" role="alert">{{ store.detailError }} <button type="button" @click="store.open()">重试红包详情</button></p><div v-if="store.detail" class="packet-detail"><p>{{ store.detail.message||'红包' }} · {{ store.detail.type }}</p><p>发送者：{{ store.detail.sender.userNickname||store.detail.sender.userName||store.detail.sender.id }}</p><p>已领取 {{ store.detail.got }}/{{ store.detail.count }}；初始奖池 {{ store.detail.poolPoints }}，税额 {{ store.detail.taxPoints }}。</p><p v-if="store.detail.recipientIds">接收人：{{ store.detail.recipientIds.join('、') }}</p><p v-if="store.detail.senderGesture!==undefined">发送者出拳：{{ hand(store.detail.senderGesture) }}</p><p v-if="store.detail.currentUserClaim">本人已领取，本次积分变化 {{ store.detail.currentUserClaim.amount }}{{ store.detail.currentUserClaim.amount<0?'（扣款）':'' }}。</p><p v-if="store.detail.got===store.detail.count">红包已领完。</p><label v-if="canClaim&&store.detail.type==='rockPaperScissors'">你的出拳<select v-model.number="gesture" :disabled="store.busy||!!store.pending||confirming"><option value="" disabled>请选择</option><option :value="0">石头</option><option :value="1">剪刀</option><option :value="2">布</option></select></label><button v-if="canClaim" type="button" :disabled="store.busy||!!store.pending||confirming" @click="claim">{{ packetRisk(store.detail.type)?'确认风险后领取':'领取一份' }}</button><p v-if="localError" role="alert">{{ localError }}</p><button type="button" :disabled="store.loading" @click="store.open()">刷新详情</button><ul><li v-for="row in store.detail.claims" :key="row.user.id">{{ row.user.userNickname||row.user.userName||row.user.id }}：{{ row.amount }}积分{{ row.amount<0?'（扣款）':'' }} · {{ new Date(row.claimedAt).toLocaleString() }}<span v-if="row.gesture!==undefined"> · {{ hand(row.gesture) }} / {{ row.outcome }}，退回发送者 {{ row.senderRefundPoints }}积分</span></li></ul></div><p v-else-if="!store.loading&&!store.detailError">红包详情尚未就绪。</p><p>此入口仅支持v3新核心红包；历史红包不自动转换。查看详情不会领取。</p></FpDialog></template>
<style scoped lang="scss">.packet-detail{overflow-wrap:anywhere}p,li,label{font-size:13px}ul{padding-left:20px}button,select{font:inherit;margin:4px;padding:5px 8px;border:1px solid var(--fp-border);border-radius:5px;background:var(--fp-card);color:var(--fp-text)}[role=alert]{color:#bd503c}</style>
